/// Contains information about a bot
class TdBotInfo extends TdObject {
  final String shortDescription;
  final String description;
  final TdPhoto? photo;
  final TdAnimation? animation;
  final TdBotMenuButton? menuButton;
  final List<TdBotCommand> commands;
  final String privacyPolicyUrl;
  final TdChatAdministratorRights? defaultGroupAdministratorRights;
  final TdChatAdministratorRights? defaultChannelAdministratorRights;
  final TdAffiliateProgramInfo? affiliateProgram;
  final int webAppBackgroundLightColor;
  final int webAppBackgroundDarkColor;
  final int webAppHeaderLightColor;
  final int webAppHeaderDarkColor;
  final TdBotVerificationParameters? verificationParameters;
  final bool canGetRevenueStatistics;
  final bool canManageEmojiStatus;
  final bool hasMediaPreviews;
  final TdInternalLinkType? editCommandsLink;
  final TdInternalLinkType? editDescriptionLink;
  final TdInternalLinkType? editDescriptionMediaLink;
  final TdInternalLinkType? editSettingsLink;

  TdBotInfo({
    required this.shortDescription,
    required this.description,
    this.photo,
    this.animation,
    this.menuButton,
    required this.commands,
    required this.privacyPolicyUrl,
    this.defaultGroupAdministratorRights,
    this.defaultChannelAdministratorRights,
    this.affiliateProgram,
    required this.webAppBackgroundLightColor,
    required this.webAppBackgroundDarkColor,
    required this.webAppHeaderLightColor,
    required this.webAppHeaderDarkColor,
    this.verificationParameters,
    required this.canGetRevenueStatistics,
    required this.canManageEmojiStatus,
    required this.hasMediaPreviews,
    this.editCommandsLink,
    this.editDescriptionLink,
    this.editDescriptionMediaLink,
    this.editSettingsLink,
  });

  @override
  String get tdType => 'botInfo';

  factory TdBotInfo.fromMap(Map<String, dynamic> map) {
    return TdBotInfo(
      shortDescription: map['short_description'] as String? ?? '',
      description: map['description'] as String? ?? '',
      photo: map['photo'] != null ? TdPhoto.fromMap(map['photo'] as Map<String, dynamic>) : null,
      animation: map['animation'] != null ? TdAnimation.fromMap(map['animation'] as Map<String, dynamic>) : null,
      menuButton: map['menu_button'] != null ? TdBotMenuButton.fromMap(map['menu_button'] as Map<String, dynamic>) : null,
      commands: (map['commands'] as List<dynamic>?)?.map((e) => TdBotCommand.fromMap(e as Map<String, dynamic>)).whereType<TdBotCommand>().toList() ?? [],
      privacyPolicyUrl: map['privacy_policy_url'] as String? ?? '',
      defaultGroupAdministratorRights: map['default_group_administrator_rights'] != null ? TdChatAdministratorRights.fromMap(map['default_group_administrator_rights'] as Map<String, dynamic>) : null,
      defaultChannelAdministratorRights: map['default_channel_administrator_rights'] != null ? TdChatAdministratorRights.fromMap(map['default_channel_administrator_rights'] as Map<String, dynamic>) : null,
      affiliateProgram: map['affiliate_program'] != null ? TdAffiliateProgramInfo.fromMap(map['affiliate_program'] as Map<String, dynamic>) : null,
      webAppBackgroundLightColor: map['web_app_background_light_color'] as int? ?? 0,
      webAppBackgroundDarkColor: map['web_app_background_dark_color'] as int? ?? 0,
      webAppHeaderLightColor: map['web_app_header_light_color'] as int? ?? 0,
      webAppHeaderDarkColor: map['web_app_header_dark_color'] as int? ?? 0,
      verificationParameters: map['verification_parameters'] != null ? TdBotVerificationParameters.fromMap(map['verification_parameters'] as Map<String, dynamic>) : null,
      canGetRevenueStatistics: map['can_get_revenue_statistics'] as bool? ?? false,
      canManageEmojiStatus: map['can_manage_emoji_status'] as bool? ?? false,
      hasMediaPreviews: map['has_media_previews'] as bool? ?? false,
      editCommandsLink: map['edit_commands_link'] != null ? TdInternalLinkType.fromMap(map['edit_commands_link'] as Map<String, dynamic>) : null,
      editDescriptionLink: map['edit_description_link'] != null ? TdInternalLinkType.fromMap(map['edit_description_link'] as Map<String, dynamic>) : null,
      editDescriptionMediaLink: map['edit_description_media_link'] != null ? TdInternalLinkType.fromMap(map['edit_description_media_link'] as Map<String, dynamic>) : null,
      editSettingsLink: map['edit_settings_link'] != null ? TdInternalLinkType.fromMap(map['edit_settings_link'] as Map<String, dynamic>) : null,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'botInfo',
      'short_description': shortDescription,
      'description': description,
      'photo': photo?.toMap(),
      'animation': animation?.toMap(),
      'menu_button': menuButton?.toMap(),
      'commands': commands.map((e) => e.toMap()).toList(),
      'privacy_policy_url': privacyPolicyUrl,
      'default_group_administrator_rights': defaultGroupAdministratorRights?.toMap(),
      'default_channel_administrator_rights': defaultChannelAdministratorRights?.toMap(),
      'affiliate_program': affiliateProgram?.toMap(),
      'web_app_background_light_color': webAppBackgroundLightColor,
      'web_app_background_dark_color': webAppBackgroundDarkColor,
      'web_app_header_light_color': webAppHeaderLightColor,
      'web_app_header_dark_color': webAppHeaderDarkColor,
      'verification_parameters': verificationParameters?.toMap(),
      'can_get_revenue_statistics': canGetRevenueStatistics,
      'can_manage_emoji_status': canManageEmojiStatus,
      'has_media_previews': hasMediaPreviews,
      'edit_commands_link': editCommandsLink?.toMap(),
      'edit_description_link': editDescriptionLink?.toMap(),
      'edit_description_media_link': editDescriptionMediaLink?.toMap(),
      'edit_settings_link': editSettingsLink?.toMap(),
    };
  }
