/// A chat. (Can be a private chat, basic group, supergroup, or secret chat)
class TdChat extends TdObject {
  final int id;
  final TdChatType? type;
  final String title;
  final TdChatPhotoInfo? photo;
  final int accentColorId;
  final int backgroundCustomEmojiId;
  final TdUpgradedGiftColors? upgradedGiftColors;
  final int profileAccentColorId;
  final int profileBackgroundCustomEmojiId;
  final TdChatPermissions? permissions;
  final TdMessage? lastMessage;
  final List<TdChatPosition> positions;
  final List<TdChatList> chatLists;
  final TdMessageSender? messageSenderId;
  final TdBlockList? blockList;
  final bool hasProtectedContent;
  final bool isTranslatable;
  final bool isMarkedAsUnread;
  final bool viewAsTopics;
  final bool hasScheduledMessages;
  final bool canBeDeletedOnlyForSelf;
  final bool canBeDeletedForAllUsers;
  final bool canBeReported;
  final bool defaultDisableNotification;
  final int unreadCount;
  final int lastReadInboxMessageId;
  final int lastReadOutboxMessageId;
  final int unreadMentionCount;
  final int unreadReactionCount;
  final TdChatNotificationSettings? notificationSettings;
  final TdChatAvailableReactions? availableReactions;
  final int messageAutoDeleteTime;
  final TdEmojiStatus? emojiStatus;
  final TdChatBackground? background;
  final TdChatTheme? theme;
  final TdChatActionBar? actionBar;
  final TdBusinessBotManageBar? businessBotManageBar;
  final TdVideoChat? videoChat;
  final TdChatJoinRequestsInfo? pendingJoinRequests;
  final int replyMarkupMessageId;
  final TdDraftMessage? draftMessage;
  final String clientData;

  TdChat({
    required this.id,
    this.type,
    required this.title,
    this.photo,
    required this.accentColorId,
    required this.backgroundCustomEmojiId,
    this.upgradedGiftColors,
    required this.profileAccentColorId,
    required this.profileBackgroundCustomEmojiId,
    this.permissions,
    this.lastMessage,
    required this.positions,
    required this.chatLists,
    this.messageSenderId,
    this.blockList,
    required this.hasProtectedContent,
    required this.isTranslatable,
    required this.isMarkedAsUnread,
    required this.viewAsTopics,
    required this.hasScheduledMessages,
    required this.canBeDeletedOnlyForSelf,
    required this.canBeDeletedForAllUsers,
    required this.canBeReported,
    required this.defaultDisableNotification,
    required this.unreadCount,
    required this.lastReadInboxMessageId,
    required this.lastReadOutboxMessageId,
    required this.unreadMentionCount,
    required this.unreadReactionCount,
    this.notificationSettings,
    this.availableReactions,
    required this.messageAutoDeleteTime,
    this.emojiStatus,
    this.background,
    this.theme,
    this.actionBar,
    this.businessBotManageBar,
    this.videoChat,
    this.pendingJoinRequests,
    required this.replyMarkupMessageId,
    this.draftMessage,
    required this.clientData,
  });

  @override
  String get tdType => 'chat';

  factory TdChat.fromMap(Map<String, dynamic> map) {
    return TdChat(
      id: map['id'] as int? ?? 0,
      type: map['type'] != null ? TdChatType.fromMap(map['type'] as Map<String, dynamic>) : null,
      title: map['title'] as String? ?? '',
      photo: map['photo'] != null ? TdChatPhotoInfo.fromMap(map['photo'] as Map<String, dynamic>) : null,
      accentColorId: map['accent_color_id'] as int? ?? 0,
      backgroundCustomEmojiId: map['background_custom_emoji_id'] as int? ?? 0,
      upgradedGiftColors: map['upgraded_gift_colors'] != null ? TdUpgradedGiftColors.fromMap(map['upgraded_gift_colors'] as Map<String, dynamic>) : null,
      profileAccentColorId: map['profile_accent_color_id'] as int? ?? 0,
      profileBackgroundCustomEmojiId: map['profile_background_custom_emoji_id'] as int? ?? 0,
      permissions: map['permissions'] != null ? TdChatPermissions.fromMap(map['permissions'] as Map<String, dynamic>) : null,
      lastMessage: map['last_message'] != null ? TdMessage.fromMap(map['last_message'] as Map<String, dynamic>) : null,
      positions: (map['positions'] as List<dynamic>?)?.map((e) => TdChatPosition.fromMap(e as Map<String, dynamic>)).whereType<TdChatPosition>().toList() ?? [],
      chatLists: (map['chat_lists'] as List<dynamic>?)?.map((e) => TdChatList.fromMap(e as Map<String, dynamic>)).whereType<TdChatList>().toList() ?? [],
      messageSenderId: map['message_sender_id'] != null ? TdMessageSender.fromMap(map['message_sender_id'] as Map<String, dynamic>) : null,
      blockList: map['block_list'] != null ? TdBlockList.fromMap(map['block_list'] as Map<String, dynamic>) : null,
      hasProtectedContent: map['has_protected_content'] as bool? ?? false,
      isTranslatable: map['is_translatable'] as bool? ?? false,
      isMarkedAsUnread: map['is_marked_as_unread'] as bool? ?? false,
      viewAsTopics: map['view_as_topics'] as bool? ?? false,
      hasScheduledMessages: map['has_scheduled_messages'] as bool? ?? false,
      canBeDeletedOnlyForSelf: map['can_be_deleted_only_for_self'] as bool? ?? false,
      canBeDeletedForAllUsers: map['can_be_deleted_for_all_users'] as bool? ?? false,
      canBeReported: map['can_be_reported'] as bool? ?? false,
      defaultDisableNotification: map['default_disable_notification'] as bool? ?? false,
      unreadCount: map['unread_count'] as int? ?? 0,
      lastReadInboxMessageId: map['last_read_inbox_message_id'] as int? ?? 0,
      lastReadOutboxMessageId: map['last_read_outbox_message_id'] as int? ?? 0,
      unreadMentionCount: map['unread_mention_count'] as int? ?? 0,
      unreadReactionCount: map['unread_reaction_count'] as int? ?? 0,
      notificationSettings: map['notification_settings'] != null ? TdChatNotificationSettings.fromMap(map['notification_settings'] as Map<String, dynamic>) : null,
      availableReactions: map['available_reactions'] != null ? TdChatAvailableReactions.fromMap(map['available_reactions'] as Map<String, dynamic>) : null,
      messageAutoDeleteTime: map['message_auto_delete_time'] as int? ?? 0,
      emojiStatus: map['emoji_status'] != null ? TdEmojiStatus.fromMap(map['emoji_status'] as Map<String, dynamic>) : null,
      background: map['background'] != null ? TdChatBackground.fromMap(map['background'] as Map<String, dynamic>) : null,
      theme: map['theme'] != null ? TdChatTheme.fromMap(map['theme'] as Map<String, dynamic>) : null,
      actionBar: map['action_bar'] != null ? TdChatActionBar.fromMap(map['action_bar'] as Map<String, dynamic>) : null,
      businessBotManageBar: map['business_bot_manage_bar'] != null ? TdBusinessBotManageBar.fromMap(map['business_bot_manage_bar'] as Map<String, dynamic>) : null,
      videoChat: map['video_chat'] != null ? TdVideoChat.fromMap(map['video_chat'] as Map<String, dynamic>) : null,
      pendingJoinRequests: map['pending_join_requests'] != null ? TdChatJoinRequestsInfo.fromMap(map['pending_join_requests'] as Map<String, dynamic>) : null,
      replyMarkupMessageId: map['reply_markup_message_id'] as int? ?? 0,
      draftMessage: map['draft_message'] != null ? TdDraftMessage.fromMap(map['draft_message'] as Map<String, dynamic>) : null,
      clientData: map['client_data'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'chat',
      'id': id,
      'type': type?.toMap(),
      'title': title,
      'photo': photo?.toMap(),
      'accent_color_id': accentColorId,
      'background_custom_emoji_id': backgroundCustomEmojiId,
      'upgraded_gift_colors': upgradedGiftColors?.toMap(),
      'profile_accent_color_id': profileAccentColorId,
      'profile_background_custom_emoji_id': profileBackgroundCustomEmojiId,
      'permissions': permissions?.toMap(),
      'last_message': lastMessage?.toMap(),
      'positions': positions.map((e) => e.toMap()).toList(),
      'chat_lists': chatLists.map((e) => e.toMap()).toList(),
      'message_sender_id': messageSenderId?.toMap(),
      'block_list': blockList?.toMap(),
      'has_protected_content': hasProtectedContent,
      'is_translatable': isTranslatable,
      'is_marked_as_unread': isMarkedAsUnread,
      'view_as_topics': viewAsTopics,
      'has_scheduled_messages': hasScheduledMessages,
      'can_be_deleted_only_for_self': canBeDeletedOnlyForSelf,
      'can_be_deleted_for_all_users': canBeDeletedForAllUsers,
      'can_be_reported': canBeReported,
      'default_disable_notification': defaultDisableNotification,
      'unread_count': unreadCount,
      'last_read_inbox_message_id': lastReadInboxMessageId,
      'last_read_outbox_message_id': lastReadOutboxMessageId,
      'unread_mention_count': unreadMentionCount,
      'unread_reaction_count': unreadReactionCount,
      'notification_settings': notificationSettings?.toMap(),
      'available_reactions': availableReactions?.toMap(),
      'message_auto_delete_time': messageAutoDeleteTime,
      'emoji_status': emojiStatus?.toMap(),
      'background': background?.toMap(),
      'theme': theme?.toMap(),
      'action_bar': actionBar?.toMap(),
      'business_bot_manage_bar': businessBotManageBar?.toMap(),
      'video_chat': videoChat?.toMap(),
      'pending_join_requests': pendingJoinRequests?.toMap(),
      'reply_markup_message_id': replyMarkupMessageId,
      'draft_message': draftMessage?.toMap(),
      'client_data': clientData,
    };
  }
}


