  final String name;
  final TdThemeSettings? lightSettings;
  final TdThemeSettings? darkSettings;

  TdEmojiChatTheme({
    required this.name,
    this.lightSettings,
    this.darkSettings,
  });

  @override
  String get tdType => 'emojiChatTheme';

  factory TdEmojiChatTheme.fromMap(Map<String, dynamic> map) {
    return TdEmojiChatTheme(
      name: map['name'] as String? ?? '',
      lightSettings: map['light_settings'] != null ? TdThemeSettings.fromMap(map['light_settings'] as Map<String, dynamic>) : null,
      darkSettings: map['dark_settings'] != null ? TdThemeSettings.fromMap(map['dark_settings'] as Map<String, dynamic>) : null,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'emojiChatTheme',
      'name': name,
      'light_settings': lightSettings?.toMap(),
      'dark_settings': darkSettings?.toMap(),
    };
  }
}


