/// Contains information about an emoji reaction
class TdEmojiReaction extends TdObject {
  final String emoji;
  final String title;
  final bool isActive;
  final TdSticker? staticIcon;
  final TdSticker? appearAnimation;
  final TdSticker? selectAnimation;
  final TdSticker? activateAnimation;
  final TdSticker? effectAnimation;
  final TdSticker? aroundAnimation;
  final TdSticker? centerAnimation;

  TdEmojiReaction({
    required this.emoji,
    required this.title,
    required this.isActive,
    this.staticIcon,
    this.appearAnimation,
    this.selectAnimation,
    this.activateAnimation,
    this.effectAnimation,
    this.aroundAnimation,
    this.centerAnimation,
  });

  @override
  String get tdType => 'emojiReaction';

  factory TdEmojiReaction.fromMap(Map<String, dynamic> map) {
    return TdEmojiReaction(
      emoji: map['emoji'] as String? ?? '',
      title: map['title'] as String? ?? '',
      isActive: map['is_active'] as bool? ?? false,
      staticIcon: map['static_icon'] != null ? TdSticker.fromMap(map['static_icon'] as Map<String, dynamic>) : null,
      appearAnimation: map['appear_animation'] != null ? TdSticker.fromMap(map['appear_animation'] as Map<String, dynamic>) : null,
      selectAnimation: map['select_animation'] != null ? TdSticker.fromMap(map['select_animation'] as Map<String, dynamic>) : null,
      activateAnimation: map['activate_animation'] != null ? TdSticker.fromMap(map['activate_animation'] as Map<String, dynamic>) : null,
      effectAnimation: map['effect_animation'] != null ? TdSticker.fromMap(map['effect_animation'] as Map<String, dynamic>) : null,
      aroundAnimation: map['around_animation'] != null ? TdSticker.fromMap(map['around_animation'] as Map<String, dynamic>) : null,
      centerAnimation: map['center_animation'] != null ? TdSticker.fromMap(map['center_animation'] as Map<String, dynamic>) : null,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'emojiReaction',
      'emoji': emoji,
      'title': title,
      'is_active': isActive,
      'static_icon': staticIcon?.toMap(),
      'appear_animation': appearAnimation?.toMap(),
      'select_animation': selectAnimation?.toMap(),
      'activate_animation': activateAnimation?.toMap(),
      'effect_animation': effectAnimation?.toMap(),
      'around_animation': aroundAnimation?.toMap(),
      'center_animation': centerAnimation?.toMap(),
    };
  }
}


