/// Contains information about an encrypted Telegram Passport element; for bots only
class TdEncryptedPassportElement extends TdObject {
  final TdPassportElementType? type;
  final String data;
  final TdDatedFile? frontSide;
  final TdDatedFile? reverseSide;
  final TdDatedFile? selfie;
  final List<TdDatedFile> translation;
  final List<TdDatedFile> files;
  final String value;
  final String hash;

  TdEncryptedPassportElement({
    this.type,
    required this.data,
    this.frontSide,
    this.reverseSide,
    this.selfie,
    required this.translation,
    required this.files,
    required this.value,
    required this.hash,
  });

  @override
  String get tdType => 'encryptedPassportElement';

  factory TdEncryptedPassportElement.fromMap(Map<String, dynamic> map) {
    return TdEncryptedPassportElement(
      type: map['type'] != null ? TdPassportElementType.fromMap(map['type'] as Map<String, dynamic>) : null,
      data: map['data'] as String? ?? '',
      frontSide: map['front_side'] != null ? TdDatedFile.fromMap(map['front_side'] as Map<String, dynamic>) : null,
      reverseSide: map['reverse_side'] != null ? TdDatedFile.fromMap(map['reverse_side'] as Map<String, dynamic>) : null,
      selfie: map['selfie'] != null ? TdDatedFile.fromMap(map['selfie'] as Map<String, dynamic>) : null,
      translation: (map['translation'] as List<dynamic>?)?.map((e) => TdDatedFile.fromMap(e as Map<String, dynamic>)).whereType<TdDatedFile>().toList() ?? [],
      files: (map['files'] as List<dynamic>?)?.map((e) => TdDatedFile.fromMap(e as Map<String, dynamic>)).whereType<TdDatedFile>().toList() ?? [],
      value: map['value'] as String? ?? '',
      hash: map['hash'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'encryptedPassportElement',
      'type': type?.toMap(),
      'data': data,
      'front_side': frontSide?.toMap(),
      'reverse_side': reverseSide?.toMap(),
      'selfie': selfie?.toMap(),
      'translation': translation.map((e) => e.toMap()).toList(),
      'files': files.map((e) => e.toMap()).toList(),
      'value': value,
      'hash': hash,
    };
  }
}


