  final TdRemoteFile? remote;

  TdFile({
    required this.id,
    required this.size,
    required this.expectedSize,
    this.local,
    this.remote,
  });

  @override
  String get tdType => 'file';

  factory TdFile.fromMap(Map<String, dynamic> map) {
    return TdFile(
      id: map['id'] as int? ?? 0,
      size: map['size'] as int? ?? 0,
      expectedSize: map['expected_size'] as int? ?? 0,
      local: map['local'] != null ? TdLocalFile.fromMap(map['local'] as Map<String, dynamic>) : null,
      remote: map['remote'] != null ? TdRemoteFile.fromMap(map['remote'] as Map<String, dynamic>) : null,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'file',
      'id': id,
      'size': size,
      'expected_size': expectedSize,
      'local': local?.toMap(),
      'remote': remote?.toMap(),
    };
  }
}


