  final String author;
  final TdLinkPreviewType? type;
  final bool hasLargeMedia;
  final bool showLargeMedia;
  final bool showMediaAboveDescription;
  final bool skipConfirmation;
  final bool showAboveText;
  final int instantViewVersion;

  TdLinkPreview({
    required this.url,
    required this.displayUrl,
    required this.siteName,
    required this.title,
    this.description,
    required this.author,
    this.type,
    required this.hasLargeMedia,
    required this.showLargeMedia,
    required this.showMediaAboveDescription,
    required this.skipConfirmation,
    required this.showAboveText,
    required this.instantViewVersion,
  });

  @override
  String get tdType => 'linkPreview';

  factory TdLinkPreview.fromMap(Map<String, dynamic> map) {
    return TdLinkPreview(
      url: map['url'] as String? ?? '',
      displayUrl: map['display_url'] as String? ?? '',
      siteName: map['site_name'] as String? ?? '',
      title: map['title'] as String? ?? '',
      description: map['description'] != null ? TdFormattedText.fromMap(map['description'] as Map<String, dynamic>) : null,
      author: map['author'] as String? ?? '',
      type: map['type'] != null ? TdLinkPreviewType.fromMap(map['type'] as Map<String, dynamic>) : null,
      hasLargeMedia: map['has_large_media'] as bool? ?? false,
      showLargeMedia: map['show_large_media'] as bool? ?? false,
      showMediaAboveDescription: map['show_media_above_description'] as bool? ?? false,
      skipConfirmation: map['skip_confirmation'] as bool? ?? false,
      showAboveText: map['show_above_text'] as bool? ?? false,
      instantViewVersion: map['instant_view_version'] as int? ?? 0,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'linkPreview',
      'url': url,
      'display_url': displayUrl,
      'site_name': siteName,
      'title': title,
      'description': description?.toMap(),
      'author': author,
      'type': type?.toMap(),
      'has_large_media': hasLargeMedia,
      'show_large_media': showLargeMedia,
      'show_media_above_description': showMediaAboveDescription,
      'skip_confirmation': skipConfirmation,
      'show_above_text': showAboveText,
      'instant_view_version': instantViewVersion,
    };
  }
}


