      chatId: map['chat_id'] as int? ?? 0,
      sendingState: map['sending_state'] != null ? TdMessageSendingState.fromMap(map['sending_state'] as Map<String, dynamic>) : null,
      schedulingState: map['scheduling_state'] != null ? TdMessageSchedulingState.fromMap(map['scheduling_state'] as Map<String, dynamic>) : null,
      isOutgoing: map['is_outgoing'] as bool? ?? false,
      isPinned: map['is_pinned'] as bool? ?? false,
      isFromOffline: map['is_from_offline'] as bool? ?? false,
      canBeSaved: map['can_be_saved'] as bool? ?? false,
      hasTimestampedMedia: map['has_timestamped_media'] as bool? ?? false,
      isChannelPost: map['is_channel_post'] as bool? ?? false,
      isPaidStarSuggestedPost: map['is_paid_star_suggested_post'] as bool? ?? false,
      isPaidTonSuggestedPost: map['is_paid_ton_suggested_post'] as bool? ?? false,
      containsUnreadMention: map['contains_unread_mention'] as bool? ?? false,
