      editDate: map['edit_date'] as int? ?? 0,
      forwardInfo: map['forward_info'] != null ? TdMessageForwardInfo.fromMap(map['forward_info'] as Map<String, dynamic>) : null,
      importInfo: map['import_info'] != null ? TdMessageImportInfo.fromMap(map['import_info'] as Map<String, dynamic>) : null,
      interactionInfo: map['interaction_info'] != null ? TdMessageInteractionInfo.fromMap(map['interaction_info'] as Map<String, dynamic>) : null,
      unreadReactions: (map['unread_reactions'] as List<dynamic>?)?.map((e) => TdUnreadReaction.fromMap(e as Map<String, dynamic>)).whereType<TdUnreadReaction>().toList() ?? [],
      factCheck: map['fact_check'] != null ? TdFactCheck.fromMap(map['fact_check'] as Map<String, dynamic>) : null,
      suggestedPostInfo: map['suggested_post_info'] != null ? TdSuggestedPostInfo.fromMap(map['suggested_post_info'] as Map<String, dynamic>) : null,
      replyTo: map['reply_to'] != null ? TdMessageReplyTo.fromMap(map['reply_to'] as Map<String, dynamic>) : null,
      topicId: map['topic_id'] != null ? TdMessageTopic.fromMap(map['topic_id'] as Map<String, dynamic>) : null,
      selfDestructType: map['self_destruct_type'] != null ? TdMessageSelfDestructType.fromMap(map['self_destruct_type'] as Map<String, dynamic>) : null,
      selfDestructIn: (map['self_destruct_in'] as num?)?.toDouble() ?? 0.0,
