      viaBotUserId: map['via_bot_user_id'] as int? ?? 0,
      senderBusinessBotUserId: map['sender_business_bot_user_id'] as int? ?? 0,
      senderBoostCount: map['sender_boost_count'] as int? ?? 0,
      paidMessageStarCount: map['paid_message_star_count'] as int? ?? 0,
