      mediaAlbumId: map['media_album_id'] as int? ?? 0,
      effectId: map['effect_id'] as int? ?? 0,
      restrictionInfo: map['restriction_info'] != null ? TdRestrictionInfo.fromMap(map['restriction_info'] as Map<String, dynamic>) : null,
      content: map['content'] != null ? TdMessageContent.fromMap(map['content'] as Map<String, dynamic>) : null,
