      'import_info': importInfo?.toMap(),
      'interaction_info': interactionInfo?.toMap(),
      'unread_reactions': unreadReactions.map((e) => e.toMap()).toList(),
      'fact_check': factCheck?.toMap(),
      'suggested_post_info': suggestedPostInfo?.toMap(),
      'reply_to': replyTo?.toMap(),
      'topic_id': topicId?.toMap(),
      'self_destruct_type': selfDestructType?.toMap(),
