    required this.isPinned,
  });

  @override
  String get tdType => 'pushMessageContentAnimation';

  factory TdPushMessageContentAnimation.fromMap(Map<String, dynamic> map) {
    return TdPushMessageContentAnimation(
      animation: map['animation'] != null ? TdAnimation.fromMap(map['animation'] as Map<String, dynamic>) : null,
      caption: map['caption'] as String? ?? '',
      isPinned: map['is_pinned'] as bool? ?? false,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'pushMessageContentAnimation',
      'animation': animation?.toMap(),
      'caption': caption,
      'is_pinned': isPinned,
    };
  }
}


