/// Contains information about one session in a Telegram application used by the current user. Sessions ...
class TdSession extends TdObject {
  final int id;
  final bool isCurrent;
  final bool isPasswordPending;
  final bool isUnconfirmed;
  final bool canAcceptSecretChats;
  final bool canAcceptCalls;
  final TdSessionType? type;
  final int apiId;
  final String applicationName;
  final String applicationVersion;
  final bool isOfficialApplication;
  final String deviceModel;
  final String platform;
  final String systemVersion;
  final int logInDate;
  final int lastActiveDate;
  final String ipAddress;
  final String location;

  TdSession({
    required this.id,
    required this.isCurrent,
    required this.isPasswordPending,
    required this.isUnconfirmed,
    required this.canAcceptSecretChats,
    required this.canAcceptCalls,
    this.type,
    required this.apiId,
    required this.applicationName,
    required this.applicationVersion,
    required this.isOfficialApplication,
    required this.deviceModel,
    required this.platform,
    required this.systemVersion,
    required this.logInDate,
    required this.lastActiveDate,
    required this.ipAddress,
    required this.location,
  });

  @override
  String get tdType => 'session';

  factory TdSession.fromMap(Map<String, dynamic> map) {
    return TdSession(
      id: map['id'] as int? ?? 0,
      isCurrent: map['is_current'] as bool? ?? false,
      isPasswordPending: map['is_password_pending'] as bool? ?? false,
      isUnconfirmed: map['is_unconfirmed'] as bool? ?? false,
      canAcceptSecretChats: map['can_accept_secret_chats'] as bool? ?? false,
      canAcceptCalls: map['can_accept_calls'] as bool? ?? false,
      type: map['type'] != null ? TdSessionType.fromMap(map['type'] as Map<String, dynamic>) : null,
      apiId: map['api_id'] as int? ?? 0,
      applicationName: map['application_name'] as String? ?? '',
      applicationVersion: map['application_version'] as String? ?? '',
      isOfficialApplication: map['is_official_application'] as bool? ?? false,
      deviceModel: map['device_model'] as String? ?? '',
      platform: map['platform'] as String? ?? '',
      systemVersion: map['system_version'] as String? ?? '',
      logInDate: map['log_in_date'] as int? ?? 0,
      lastActiveDate: map['last_active_date'] as int? ?? 0,
      ipAddress: map['ip_address'] as String? ?? '',
      location: map['location'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'session',
      'id': id,
      'is_current': isCurrent,
      'is_password_pending': isPasswordPending,
      'is_unconfirmed': isUnconfirmed,
      'can_accept_secret_chats': canAcceptSecretChats,
      'can_accept_calls': canAcceptCalls,
      'type': type?.toMap(),
      'api_id': apiId,
      'application_name': applicationName,
      'application_version': applicationVersion,
      'is_official_application': isOfficialApplication,
      'device_model': deviceModel,
      'platform': platform,
      'system_version': systemVersion,
      'log_in_date': logInDate,
      'last_active_date': lastActiveDate,
      'ip_address': ipAddress,
      'location': location,
    };
  }
}


