/// Represents a sticker set
class TdStickerSet extends TdObject {
  final int id;
  final String title;
  final String name;
  final TdThumbnail? thumbnail;
  final TdOutline? thumbnailOutline;
  final bool isOwned;
  final bool isInstalled;
  final bool isArchived;
  final bool isOfficial;
  final TdStickerType? stickerType;
  final bool needsRepainting;
  final bool isAllowedAsChatEmojiStatus;
  final bool isViewed;
  final List<TdSticker> stickers;
  final List<TdEmojis> emojis;

  TdStickerSet({
    required this.id,
    required this.title,
    required this.name,
    this.thumbnail,
    this.thumbnailOutline,
    required this.isOwned,
    required this.isInstalled,
    required this.isArchived,
    required this.isOfficial,
    this.stickerType,
    required this.needsRepainting,
    required this.isAllowedAsChatEmojiStatus,
    required this.isViewed,
    required this.stickers,
    required this.emojis,
  });

  @override
  String get tdType => 'stickerSet';

  factory TdStickerSet.fromMap(Map<String, dynamic> map) {
    return TdStickerSet(
      id: map['id'] as int? ?? 0,
      title: map['title'] as String? ?? '',
      name: map['name'] as String? ?? '',
      thumbnail: map['thumbnail'] != null ? TdThumbnail.fromMap(map['thumbnail'] as Map<String, dynamic>) : null,
      thumbnailOutline: map['thumbnail_outline'] != null ? TdOutline.fromMap(map['thumbnail_outline'] as Map<String, dynamic>) : null,
      isOwned: map['is_owned'] as bool? ?? false,
      isInstalled: map['is_installed'] as bool? ?? false,
      isArchived: map['is_archived'] as bool? ?? false,
      isOfficial: map['is_official'] as bool? ?? false,
      stickerType: map['sticker_type'] != null ? TdStickerType.fromMap(map['sticker_type'] as Map<String, dynamic>) : null,
      needsRepainting: map['needs_repainting'] as bool? ?? false,
      isAllowedAsChatEmojiStatus: map['is_allowed_as_chat_emoji_status'] as bool? ?? false,
      isViewed: map['is_viewed'] as bool? ?? false,
      stickers: (map['stickers'] as List<dynamic>?)?.map((e) => TdSticker.fromMap(e as Map<String, dynamic>)).whereType<TdSticker>().toList() ?? [],
      emojis: (map['emojis'] as List<dynamic>?)?.map((e) => TdEmojis.fromMap(e as Map<String, dynamic>)).whereType<TdEmojis>().toList() ?? [],
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'stickerSet',
      'id': id,
      'title': title,
      'name': name,
      'thumbnail': thumbnail?.toMap(),
      'thumbnail_outline': thumbnailOutline?.toMap(),
      'is_owned': isOwned,
      'is_installed': isInstalled,
      'is_archived': isArchived,
      'is_official': isOfficial,
      'sticker_type': stickerType?.toMap(),
      'needs_repainting': needsRepainting,
      'is_allowed_as_chat_emoji_status': isAllowedAsChatEmojiStatus,
      'is_viewed': isViewed,
      'stickers': stickers.map((e) => e.toMap()).toList(),
      'emojis': emojis.map((e) => e.toMap()).toList(),
    };
  }
}


