/// Represents a list of stories
class TdStories extends TdObject {
  final int totalCount;
  final List<TdStory> stories;
  final List<int> pinnedStoryIds;

  TdStories({
    required this.totalCount,
    required this.stories,
    required this.pinnedStoryIds,
  });

  @override
  String get tdType => 'stories';

  factory TdStories.fromMap(Map<String, dynamic> map) {
    return TdStories(
      totalCount: map['total_count'] as int? ?? 0,
      stories: (map['stories'] as List<dynamic>?)?.map((e) => TdStory.fromMap(e as Map<String, dynamic>)).whereType<TdStory>().toList() ?? [],
      pinnedStoryIds: (map['pinned_story_ids'] as List<dynamic>?)?.map((e) => e as int).toList() ?? [],
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'stories',
      'total_count': totalCount,
      'stories': stories.map((e) => e.toMap()).toList(),
      'pinned_story_ids': pinnedStoryIds,
    };
  }
}


/// Represents a story
class TdStory extends TdObject {
  final int id;
  final int posterChatId;
  final TdMessageSender? posterId;
  final int date;
  final bool isBeingPosted;
  final bool isBeingEdited;
  final bool isEdited;
  final bool isPostedToChatPage;
  final bool isVisibleOnlyForSelf;
  final bool canBeAddedToAlbum;
  final bool canBeDeleted;
  final bool canBeEdited;
  final bool canBeForwarded;
  final bool canBeReplied;
  final bool canSetPrivacySettings;
  final bool canToggleIsPostedToChatPage;
  final bool canGetStatistics;
  final bool canGetInteractions;
  final bool hasExpiredViewers;
  final TdStoryRepostInfo? repostInfo;
  final TdStoryInteractionInfo? interactionInfo;
  final TdReactionType? chosenReactionType;
  final TdStoryPrivacySettings? privacySettings;
  final TdStoryContent? content;
  final List<TdStoryArea> areas;
  final TdFormattedText? caption;
  final List<int> albumIds;

  TdStory({
    required this.id,
    required this.posterChatId,
    this.posterId,
    required this.date,
    required this.isBeingPosted,
    required this.isBeingEdited,
    required this.isEdited,
    required this.isPostedToChatPage,
    required this.isVisibleOnlyForSelf,
    required this.canBeAddedToAlbum,
    required this.canBeDeleted,
    required this.canBeEdited,
    required this.canBeForwarded,
    required this.canBeReplied,
    required this.canSetPrivacySettings,
    required this.canToggleIsPostedToChatPage,
    required this.canGetStatistics,
    required this.canGetInteractions,
    required this.hasExpiredViewers,
    this.repostInfo,
    this.interactionInfo,
    this.chosenReactionType,
    this.privacySettings,
    this.content,
    required this.areas,
    this.caption,
    required this.albumIds,
  });

  @override
  String get tdType => 'story';

  factory TdStory.fromMap(Map<String, dynamic> map) {
    return TdStory(
      id: map['id'] as int? ?? 0,
      posterChatId: map['poster_chat_id'] as int? ?? 0,
      posterId: map['poster_id'] != null ? TdMessageSender.fromMap(map['poster_id'] as Map<String, dynamic>) : null,
      date: map['date'] as int? ?? 0,
      isBeingPosted: map['is_being_posted'] as bool? ?? false,
      isBeingEdited: map['is_being_edited'] as bool? ?? false,
      isEdited: map['is_edited'] as bool? ?? false,
      isPostedToChatPage: map['is_posted_to_chat_page'] as bool? ?? false,
      isVisibleOnlyForSelf: map['is_visible_only_for_self'] as bool? ?? false,
      canBeAddedToAlbum: map['can_be_added_to_album'] as bool? ?? false,
      canBeDeleted: map['can_be_deleted'] as bool? ?? false,
      canBeEdited: map['can_be_edited'] as bool? ?? false,
      canBeForwarded: map['can_be_forwarded'] as bool? ?? false,
      canBeReplied: map['can_be_replied'] as bool? ?? false,
      canSetPrivacySettings: map['can_set_privacy_settings'] as bool? ?? false,
      canToggleIsPostedToChatPage: map['can_toggle_is_posted_to_chat_page'] as bool? ?? false,
      canGetStatistics: map['can_get_statistics'] as bool? ?? false,
      canGetInteractions: map['can_get_interactions'] as bool? ?? false,
      hasExpiredViewers: map['has_expired_viewers'] as bool? ?? false,
      repostInfo: map['repost_info'] != null ? TdStoryRepostInfo.fromMap(map['repost_info'] as Map<String, dynamic>) : null,
      interactionInfo: map['interaction_info'] != null ? TdStoryInteractionInfo.fromMap(map['interaction_info'] as Map<String, dynamic>) : null,
      chosenReactionType: map['chosen_reaction_type'] != null ? TdReactionType.fromMap(map['chosen_reaction_type'] as Map<String, dynamic>) : null,
      privacySettings: map['privacy_settings'] != null ? TdStoryPrivacySettings.fromMap(map['privacy_settings'] as Map<String, dynamic>) : null,
      content: map['content'] != null ? TdStoryContent.fromMap(map['content'] as Map<String, dynamic>) : null,
      areas: (map['areas'] as List<dynamic>?)?.map((e) => TdStoryArea.fromMap(e as Map<String, dynamic>)).whereType<TdStoryArea>().toList() ?? [],
      caption: map['caption'] != null ? TdFormattedText.fromMap(map['caption'] as Map<String, dynamic>) : null,
      albumIds: (map['album_ids'] as List<dynamic>?)?.map((e) => e as int).toList() ?? [],
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'story',
      'id': id,
      'poster_chat_id': posterChatId,
      'poster_id': posterId?.toMap(),
      'date': date,
      'is_being_posted': isBeingPosted,
      'is_being_edited': isBeingEdited,
      'is_edited': isEdited,
      'is_posted_to_chat_page': isPostedToChatPage,
      'is_visible_only_for_self': isVisibleOnlyForSelf,
      'can_be_added_to_album': canBeAddedToAlbum,
      'can_be_deleted': canBeDeleted,
      'can_be_edited': canBeEdited,
      'can_be_forwarded': canBeForwarded,
      'can_be_replied': canBeReplied,
      'can_set_privacy_settings': canSetPrivacySettings,
      'can_toggle_is_posted_to_chat_page': canToggleIsPostedToChatPage,
      'can_get_statistics': canGetStatistics,
      'can_get_interactions': canGetInteractions,
      'has_expired_viewers': hasExpiredViewers,
      'repost_info': repostInfo?.toMap(),
      'interaction_info': interactionInfo?.toMap(),
      'chosen_reaction_type': chosenReactionType?.toMap(),
      'privacy_settings': privacySettings?.toMap(),
      'content': content?.toMap(),
      'areas': areas.map((e) => e.toMap()).toList(),
      'caption': caption?.toMap(),
      'album_ids': albumIds,
    };
  }
}


