/// Represents a supergroup or channel with zero or more members (subscribers in the case of channels). ...
class TdSupergroup extends TdObject {
  final int id;
  final TdUsernames? usernames;
  final int date;
  final TdChatMemberStatus? status;
  final int memberCount;
  final int boostLevel;
  final bool hasAutomaticTranslation;
  final bool hasLinkedChat;
  final bool hasLocation;
  final bool signMessages;
  final bool showMessageSender;
  final bool joinToSendMessages;
  final bool joinByRequest;
  final bool isSlowModeEnabled;
  final bool isChannel;
  final bool isBroadcastGroup;
  final bool isForum;
  final bool isDirectMessagesGroup;
  final bool isAdministeredDirectMessagesGroup;
  final TdVerificationStatus? verificationStatus;
  final bool hasDirectMessagesGroup;
  final bool hasForumTabs;
  final TdRestrictionInfo? restrictionInfo;
  final int paidMessageStarCount;
  final TdActiveStoryState? activeStoryState;

  TdSupergroup({
    required this.id,
    this.usernames,
    required this.date,
    this.status,
    required this.memberCount,
    required this.boostLevel,
    required this.hasAutomaticTranslation,
    required this.hasLinkedChat,
    required this.hasLocation,
    required this.signMessages,
    required this.showMessageSender,
    required this.joinToSendMessages,
    required this.joinByRequest,
    required this.isSlowModeEnabled,
    required this.isChannel,
    required this.isBroadcastGroup,
    required this.isForum,
    required this.isDirectMessagesGroup,
    required this.isAdministeredDirectMessagesGroup,
    this.verificationStatus,
    required this.hasDirectMessagesGroup,
    required this.hasForumTabs,
    this.restrictionInfo,
    required this.paidMessageStarCount,
    this.activeStoryState,
  });

  @override
  String get tdType => 'supergroup';

  factory TdSupergroup.fromMap(Map<String, dynamic> map) {
    return TdSupergroup(
      id: map['id'] as int? ?? 0,
      usernames: map['usernames'] != null ? TdUsernames.fromMap(map['usernames'] as Map<String, dynamic>) : null,
      date: map['date'] as int? ?? 0,
      status: map['status'] != null ? TdChatMemberStatus.fromMap(map['status'] as Map<String, dynamic>) : null,
      memberCount: map['member_count'] as int? ?? 0,
      boostLevel: map['boost_level'] as int? ?? 0,
      hasAutomaticTranslation: map['has_automatic_translation'] as bool? ?? false,
      hasLinkedChat: map['has_linked_chat'] as bool? ?? false,
      hasLocation: map['has_location'] as bool? ?? false,
      signMessages: map['sign_messages'] as bool? ?? false,
      showMessageSender: map['show_message_sender'] as bool? ?? false,
      joinToSendMessages: map['join_to_send_messages'] as bool? ?? false,
      joinByRequest: map['join_by_request'] as bool? ?? false,
      isSlowModeEnabled: map['is_slow_mode_enabled'] as bool? ?? false,
      isChannel: map['is_channel'] as bool? ?? false,
      isBroadcastGroup: map['is_broadcast_group'] as bool? ?? false,
      isForum: map['is_forum'] as bool? ?? false,
      isDirectMessagesGroup: map['is_direct_messages_group'] as bool? ?? false,
      isAdministeredDirectMessagesGroup: map['is_administered_direct_messages_group'] as bool? ?? false,
      verificationStatus: map['verification_status'] != null ? TdVerificationStatus.fromMap(map['verification_status'] as Map<String, dynamic>) : null,
      hasDirectMessagesGroup: map['has_direct_messages_group'] as bool? ?? false,
      hasForumTabs: map['has_forum_tabs'] as bool? ?? false,
      restrictionInfo: map['restriction_info'] != null ? TdRestrictionInfo.fromMap(map['restriction_info'] as Map<String, dynamic>) : null,
      paidMessageStarCount: map['paid_message_star_count'] as int? ?? 0,
      activeStoryState: map['active_story_state'] != null ? TdActiveStoryState.fromMap(map['active_story_state'] as Map<String, dynamic>) : null,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'supergroup',
      'id': id,
      'usernames': usernames?.toMap(),
      'date': date,
      'status': status?.toMap(),
      'member_count': memberCount,
      'boost_level': boostLevel,
      'has_automatic_translation': hasAutomaticTranslation,
      'has_linked_chat': hasLinkedChat,
      'has_location': hasLocation,
      'sign_messages': signMessages,
      'show_message_sender': showMessageSender,
      'join_to_send_messages': joinToSendMessages,
      'join_by_request': joinByRequest,
      'is_slow_mode_enabled': isSlowModeEnabled,
      'is_channel': isChannel,
      'is_broadcast_group': isBroadcastGroup,
      'is_forum': isForum,
      'is_direct_messages_group': isDirectMessagesGroup,
      'is_administered_direct_messages_group': isAdministeredDirectMessagesGroup,
      'verification_status': verificationStatus?.toMap(),
      'has_direct_messages_group': hasDirectMessagesGroup,
      'has_forum_tabs': hasForumTabs,
      'restriction_info': restrictionInfo?.toMap(),
      'paid_message_star_count': paidMessageStarCount,
      'active_story_state': activeStoryState?.toMap(),
    };
  }
}


