/// Represents a user
class TdUser extends TdObject {
  final int id;
  final String firstName;
  final String lastName;
  final TdUsernames? usernames;
  final String phoneNumber;
  final TdUserStatus? status;
  final TdProfilePhoto? profilePhoto;
  final int accentColorId;
  final int backgroundCustomEmojiId;
  final TdUpgradedGiftColors? upgradedGiftColors;
  final int profileAccentColorId;
  final int profileBackgroundCustomEmojiId;
  final TdEmojiStatus? emojiStatus;
  final bool isContact;
  final bool isMutualContact;
  final bool isCloseFriend;
  final TdVerificationStatus? verificationStatus;
  final bool isPremium;
  final bool isSupport;
  final TdRestrictionInfo? restrictionInfo;
  final TdActiveStoryState? activeStoryState;
  final bool restrictsNewChats;
  final int paidMessageStarCount;
  final bool haveAccess;
  final TdUserType? type;
  final String languageCode;
  final bool addedToAttachmentMenu;

  TdUser({
    required this.id,
    required this.firstName,
    required this.lastName,
    this.usernames,
    required this.phoneNumber,
    this.status,
    this.profilePhoto,
    required this.accentColorId,
    required this.backgroundCustomEmojiId,
    this.upgradedGiftColors,
    required this.profileAccentColorId,
    required this.profileBackgroundCustomEmojiId,
    this.emojiStatus,
    required this.isContact,
    required this.isMutualContact,
    required this.isCloseFriend,
    this.verificationStatus,
    required this.isPremium,
    required this.isSupport,
    this.restrictionInfo,
    this.activeStoryState,
    required this.restrictsNewChats,
    required this.paidMessageStarCount,
    required this.haveAccess,
    this.type,
    required this.languageCode,
    required this.addedToAttachmentMenu,
  });

  @override
  String get tdType => 'user';

  factory TdUser.fromMap(Map<String, dynamic> map) {
    return TdUser(
      id: map['id'] as int? ?? 0,
      firstName: map['first_name'] as String? ?? '',
      lastName: map['last_name'] as String? ?? '',
      usernames: map['usernames'] != null ? TdUsernames.fromMap(map['usernames'] as Map<String, dynamic>) : null,
      phoneNumber: map['phone_number'] as String? ?? '',
      status: map['status'] != null ? TdUserStatus.fromMap(map['status'] as Map<String, dynamic>) : null,
      profilePhoto: map['profile_photo'] != null ? TdProfilePhoto.fromMap(map['profile_photo'] as Map<String, dynamic>) : null,
      accentColorId: map['accent_color_id'] as int? ?? 0,
      backgroundCustomEmojiId: map['background_custom_emoji_id'] as int? ?? 0,
      upgradedGiftColors: map['upgraded_gift_colors'] != null ? TdUpgradedGiftColors.fromMap(map['upgraded_gift_colors'] as Map<String, dynamic>) : null,
      profileAccentColorId: map['profile_accent_color_id'] as int? ?? 0,
      profileBackgroundCustomEmojiId: map['profile_background_custom_emoji_id'] as int? ?? 0,
      emojiStatus: map['emoji_status'] != null ? TdEmojiStatus.fromMap(map['emoji_status'] as Map<String, dynamic>) : null,
      isContact: map['is_contact'] as bool? ?? false,
      isMutualContact: map['is_mutual_contact'] as bool? ?? false,
      isCloseFriend: map['is_close_friend'] as bool? ?? false,
      verificationStatus: map['verification_status'] != null ? TdVerificationStatus.fromMap(map['verification_status'] as Map<String, dynamic>) : null,
      isPremium: map['is_premium'] as bool? ?? false,
      isSupport: map['is_support'] as bool? ?? false,
      restrictionInfo: map['restriction_info'] != null ? TdRestrictionInfo.fromMap(map['restriction_info'] as Map<String, dynamic>) : null,
      activeStoryState: map['active_story_state'] != null ? TdActiveStoryState.fromMap(map['active_story_state'] as Map<String, dynamic>) : null,
      restrictsNewChats: map['restricts_new_chats'] as bool? ?? false,
      paidMessageStarCount: map['paid_message_star_count'] as int? ?? 0,
      haveAccess: map['have_access'] as bool? ?? false,
      type: map['type'] != null ? TdUserType.fromMap(map['type'] as Map<String, dynamic>) : null,
      languageCode: map['language_code'] as String? ?? '',
      addedToAttachmentMenu: map['added_to_attachment_menu'] as bool? ?? false,
    );
  }

  @override
  Map<String, dynamic> toMap() {
    return {
      '@type': 'user',
      'id': id,
      'first_name': firstName,
      'last_name': lastName,
      'usernames': usernames?.toMap(),
      'phone_number': phoneNumber,
      'status': status?.toMap(),
      'profile_photo': profilePhoto?.toMap(),
      'accent_color_id': accentColorId,
      'background_custom_emoji_id': backgroundCustomEmojiId,
      'upgraded_gift_colors': upgradedGiftColors?.toMap(),
      'profile_accent_color_id': profileAccentColorId,
      'profile_background_custom_emoji_id': profileBackgroundCustomEmojiId,
      'emoji_status': emojiStatus?.toMap(),
      'is_contact': isContact,
      'is_mutual_contact': isMutualContact,
      'is_close_friend': isCloseFriend,
      'verification_status': verificationStatus?.toMap(),
      'is_premium': isPremium,
      'is_support': isSupport,
      'restriction_info': restrictionInfo?.toMap(),
      'active_story_state': activeStoryState?.toMap(),
      'restricts_new_chats': restrictsNewChats,
      'paid_message_star_count': paidMessageStarCount,
      'have_access': haveAccess,
      'type': type?.toMap(),
      'language_code': languageCode,
      'added_to_attachment_menu': addedToAttachmentMenu,
    };
  }
}


